let currentUraCif = null;

const UGX = 3800;
function fmt(n){ return '$'+Math.round(n).toLocaleString('en-US'); }
function fmtU(n){ return 'UGX '+(Math.round(n*UGX)).toLocaleString('en-US'); }

function onMakeChange(){
  const make = document.getElementById('make').value;
  const modelSel = document.getElementById('model');
  const yearSel = document.getElementById('year');
  modelSel.innerHTML='<option value="">Select model...</option>';
  yearSel.innerHTML='<option value="">Select year...</option>';
  modelSel.disabled=!make; yearSel.disabled=true;
  resetUra();
  if(!make) return;
  const models = [...new Set(DB.filter(v=>v.make===make).map(v=>v.model))].sort();
  models.forEach(m=>{ const o=document.createElement('option'); o.value=m; o.textContent=m; modelSel.appendChild(o); });
  modelSel.disabled=false;
}

function onModelChange(){
  const make=document.getElementById('make').value;
  const model=document.getElementById('model').value;
  const chassisSel=document.getElementById('chassis');
  const ccSel=document.getElementById('cc');
  const yearSel=document.getElementById('year');
  chassisSel.innerHTML='<option value="">Select chassis...</option>';
  document.getElementById('cc').innerHTML='<option value="">Select engine size...</option>';
  yearSel.innerHTML='<option value="">Select year...</option>';
  yearSel.disabled=true; chassisSel.disabled=true; document.getElementById('cc').disabled=true;
  document.getElementById('chassisField').style.display='none';
  document.getElementById('ccField').style.display='none';
  resetUra(); if(!model) return;

  const matching = DB.filter(v=>v.make===make&&v.model===model);
  // Group by chassis code → year ranges
  const chassisMap={};
  matching.forEach(v=>{
    const c=v.chassis||'—';
    if(!chassisMap[c]) chassisMap[c]={min:v.year,max:v.year};
    else { if(v.year<chassisMap[c].min) chassisMap[c].min=v.year; if(v.year>chassisMap[c].max) chassisMap[c].max=v.year; }
  });
  const codes=Object.keys(chassisMap).sort();

  if(codes.length===1 && codes[0]==='—'){
    // No chassis data — skip chassis step, go straight to year
    document.getElementById('chassisField').style.display='none';
    // Still check for multiple CC options
    const ccs2=[...new Set(matching.map(v=>v.cc).filter(Boolean))].sort((a,b)=>(parseInt(a)||0)-(parseInt(b)||0));
    if(ccs2.length>1){
      document.getElementById('ccField').style.display='block';
      document.getElementById('ccHint').textContent=`${ccs2.length} options`;
      const fuelMatch2=model.match(/\((Diesel|Petrol|Electric|Hybrid|EV|CNG|LPG|Gasoline|Turbo)\)/i);
      const fuelTag2=fuelMatch2?` (${fuelMatch2[1]})`:''
      ccs2.forEach(c=>{ const o=document.createElement('option'); o.value=c; o.textContent=`${c}cc${fuelTag2}`; ccSel.appendChild(o); });
      ccSel.disabled=false;
    } else {
      const years=[...new Set(matching.map(v=>v.year).filter(y=>y>0))].sort((a,b)=>b-a);
      years.forEach(y=>{ const o=document.createElement('option'); o.value=y; o.textContent=y; yearSel.appendChild(o); });
      yearSel.disabled=false;
    }
  } else {
    // Show chassis selector
    document.getElementById('chassisField').style.display='block';
    document.getElementById('chassisHint').textContent=codes.length>1?`${codes.length} variants`:'';
    codes.forEach(c=>{
      const r=chassisMap[c];
      const label = c==='—' ? `Unknown (${r.min}–${r.max})` :
        r.min===r.max ? `${c}  ·  ${r.min}` : `${c}  ·  ${r.min}–${r.max}`;
      const o=document.createElement('option'); o.value=c; o.textContent=label;
      chassisSel.appendChild(o);
    });
    chassisSel.disabled=false;
    // Auto-select if only one chassis
    if(codes.length===1){ chassisSel.value=codes[0]; onChassisChange(); }
  }
}

function onChassisChange(){
  const make=document.getElementById('make').value;
  const model=document.getElementById('model').value;
  const chassis=document.getElementById('chassis').value;
  const ccSel=document.getElementById('cc');
  const yearSel=document.getElementById('year');
  ccSel.innerHTML='<option value="">Select engine size...</option>';
  yearSel.innerHTML='<option value="">Select year...</option>';
  ccSel.disabled=true; yearSel.disabled=true;
  document.getElementById('ccField').style.display='none';
  resetUra();
  if(!chassis) return;
  const matching=DB.filter(v=>v.make===make&&v.model===model&&(v.chassis||'—')===chassis);
  const ccs=[...new Set(matching.map(v=>v.cc).filter(Boolean))].sort((a,b)=>{
    const na=parseInt(a)||0, nb=parseInt(b)||0; return na-nb;
  });
  if(ccs.length<=1){
    // Auto-select CC, go straight to year
    document.getElementById('ccField').style.display='none';
    const years=[...new Set(matching.map(v=>v.year).filter(y=>y>0))].sort((a,b)=>b-a);
    years.forEach(y=>{ const o=document.createElement('option'); o.value=y; o.textContent=y; yearSel.appendChild(o); });
    yearSel.disabled=false;
    if(ccs.length===1){ ccSel.innerHTML=`<option value="${ccs[0]}">${ccs[0]}cc</option>`; ccSel.value=ccs[0]; }
  } else {
    document.getElementById('ccField').style.display='block';
    document.getElementById('ccHint').textContent=`${ccs.length} options`;
    const fuelMatch=model.match(/\((Diesel|Petrol|Electric|Hybrid|EV|CNG|LPG|Gasoline|Turbo)\)/i);
    const fuelTag=fuelMatch?` (${fuelMatch[1]})`:''
    ccs.forEach(c=>{
      const o=document.createElement('option');
      o.value=c;
      o.textContent=`${c}cc${fuelTag}`;
      ccSel.appendChild(o);
    });
    ccSel.disabled=false;
  }
  // Show chassis badge
  const badge=document.getElementById('chassisBadge');
  if(badge&&chassis!=='—'){ badge.innerHTML=`🔩 Chassis: <b>${chassis}</b>`; badge.style.display='flex'; }
}

function onCcChange(){
  const make=document.getElementById('make').value;
  const model=document.getElementById('model').value;
  const chassis=document.getElementById('chassis').value||'';
  const cc=document.getElementById('cc').value;
  const yearSel=document.getElementById('year');
  yearSel.innerHTML='<option value="">Select year...</option>';
  yearSel.disabled=true; resetUra();
  if(!cc) return;
  const matching=DB.filter(v=>v.make===make&&v.model===model&&
    (!chassis||chassis==='—'||(v.chassis||'—')===chassis)&&v.cc===cc);
  const years=[...new Set(matching.map(v=>v.year).filter(y=>y>0))].sort((a,b)=>b-a);
  years.forEach(y=>{ const o=document.createElement('option'); o.value=y; o.textContent=y; yearSel.appendChild(o); });
  yearSel.disabled=false;
}

function onYearChange(){
  const make=document.getElementById('make').value;
  const model=document.getElementById('model').value;
  const year=parseInt(document.getElementById('year').value);
  resetUra();
  if(!year) return;
  document.getElementById('ageWarning').classList.toggle('show', year<2011);
  const chassisVal=document.getElementById('chassis')?.value||'';
  const ccVal=document.getElementById('cc')?.value||'';
  const v=DB.find(x=>x.make===make&&x.model===model&&x.year===year&&
    (!chassisVal||chassisVal==='—'||(x.chassis||'—')===chassisVal)&&
    (!ccVal||x.cc===ccVal));
  if(v){
    currentUraCif=v.cif;
    document.getElementById('uraCifDisplay').textContent=fmt(v.cif);
    document.getElementById('uraBadge').classList.add('show');
    document.getElementById('uraNotFound').classList.remove('show');
    // Show chassis
    const chassisEl=document.getElementById('chassisBadge');
    if(v.chassis&&v.chassis!=='—'){
      chassisEl.innerHTML=`🔩 Chassis: <b>${v.chassis}</b>`;
      chassisEl.style.display='flex';
    } else {
      chassisEl.style.display='none';
    }
  } else {
    currentUraCif=null;
    document.getElementById('uraBadge').classList.remove('show');
    document.getElementById('uraNotFound').classList.add('show');
    document.getElementById('chassisBadge').style.display='none';
  }
}

// --- QUICK SEARCH LOGIC ---
function handleQuickSearch() {
  const input = document.getElementById('quickSearchInput').value.toLowerCase().trim();
  const resultsContainer = document.getElementById('quickSearchResults');
  
  if (input.length < 3) {
    resultsContainer.style.display = 'none';
    return;
  }

  // Remove hyphens and split input into separate search terms (e.g. "c180" matches "C-180")
  const normalizedInput = input.replace(/-/g, '');
  const searchTerms = normalizedInput.split(/\s+/).filter(t => t.length > 0);

  // Filter DB: a vehicle matches if ALL search terms are found in its combined details
  const matches = DB.filter(v => {
    const searchableString = `${v.make || ''} ${v.model || ''} ${v.chassis || ''}`.toLowerCase().replace(/-/g, '');
    return searchTerms.every(term => searchableString.includes(term));
  }).slice(0, 50); // Limit to 50 results for performance

  if (matches.length === 0) {
    resultsContainer.innerHTML = '<div style="padding: 12px; color: var(--muted); font-size: 13px;">No exact matches found.</div>';
    resultsContainer.style.display = 'block';
    return;
  }

  let html = '';
  matches.forEach((v, index) => {
    const chassisDisp = v.chassis && v.chassis !== '—' ? ` | Chassis: ${v.chassis}` : '';
    const ccDisp = v.cc ? ` | ${v.cc}cc` : '';
    const yearDisp = v.year > 0 ? ` | ${v.year}` : '';
    
    // Using index to pick the correct object from the matches array
    html += `
      <div class="quick-search-item" onclick='selectQuickSearchResult(${JSON.stringify(v).replace(/'/g, "&#39;")})'>
        <div class="quick-search-item-title">${v.make} ${v.model}</div>
        <div class="quick-search-item-details">${v.make}${chassisDisp}${ccDisp}${yearDisp}</div>
      </div>
    `;
  });

  resultsContainer.innerHTML = html;
  resultsContainer.style.display = 'block';
}

function selectQuickSearchResult(v) {
  // Hide search results
  document.getElementById('quickSearchResults').style.display = 'none';
  document.getElementById('quickSearchInput').value = `${v.make} ${v.model} ${v.year>0?v.year:''}`.trim();

  // 1. Set Make
  const makeSel = document.getElementById('make');
  makeSel.value = v.make;
  onMakeChange(); // populates models

  // 2. Set Model
  setTimeout(() => {
    const modelSel = document.getElementById('model');
    modelSel.value = v.model;
    onModelChange(); // populates chassis

    // 3. Set Chassis
    setTimeout(() => {
      const chassisSel = document.getElementById('chassis');
      if (!chassisSel.disabled) {
        if (chassisSel.options.length > 1 && v.chassis) {
           chassisSel.value = v.chassis === '—' ? '—' : v.chassis;
        } else if (chassisSel.options.length === 2) {
           chassisSel.selectedIndex = 1; // Auto select if only one option besides default
        }
        onChassisChange(); // populates CC
      }

      // 4. Set CC
      setTimeout(() => {
        const ccSel = document.getElementById('cc');
        if (!ccSel.disabled) {
          if(ccSel.options.length > 1 && v.cc) {
            ccSel.value = v.cc;
          } else if (ccSel.options.length === 2) {
            ccSel.selectedIndex = 1;
          }
          onCcChange(); // populates Year
        }

        // 5. Set Year
        setTimeout(() => {
           const yearSel = document.getElementById('year');
           if (!yearSel.disabled && v.year > 0) {
              yearSel.value = v.year;
           }
           onYearChange(); // Final calculation hook
        }, 10);
      }, 10);
    }, 10);
  }, 10);
}

// Close search results if clicked outside
document.addEventListener('click', function(event) {
  const container = document.getElementById('quickSearchResults');
  const input = document.getElementById('quickSearchInput');
  if (container && input) {
    if (!container.contains(event.target) && event.target !== input) {
      container.style.display = 'none';
    }
  }
});

function resetUra(){
  currentUraCif=null;
  document.getElementById('uraBadge').classList.remove('show');
  document.getElementById('uraNotFound').classList.remove('show');
  document.getElementById('ageWarning').classList.remove('show');
}

function calculate(){
  const carPrice=parseFloat(document.getElementById('carPrice').value)||0;
  const shipping=parseFloat(document.getElementById('shipping').value)||0;
  const insurance=parseFloat(document.getElementById('insurance').value)||0;
  const agentFee=parseFloat(document.getElementById('agentFee').value)||0;
  const year=parseInt(document.getElementById('year').value)||2015;
  if(carPrice<=0){ alert('Please enter your purchase price.'); return; }
  const cif = currentUraCif ? currentUraCif : (carPrice + shipping + insurance);
  const uraCifUsed = !!currentUraCif;
  const taxBase = currentUraCif || carPrice; // Still useful for labels/methodology
  const age=2026-year;
  const duty=cif*0.25;
  const vat=(cif+duty)*0.18;
  const wht=cif*0.06;
  const infra=cif*0.015;
  // Environmental Levy: 0% under 9yrs, 50% for 9-14yrs (URA verified)
  const envLevyRate=age>9?0.50:0;
  const envLevy=cif*envLevyRate;
  // Fixed UGX government fees
  const formFees=18000/UGX;
  const stampDuty=200000/UGX;
  const exciseDuty=200000/UGX;
  const regFees=1500000/UGX;
  const fixedFees=formFees+stampDuty+exciseDuty+regFees;
  const totalTaxes=duty+vat+wht+infra+envLevy+fixedFees+agentFee;
  const totalLanded=carPrice+shipping+insurance+totalTaxes;
  const taxRate=Math.round((totalTaxes/carPrice)*100);
  document.getElementById('r-cif').textContent=fmt(cif);
  document.getElementById('r-duty').textContent=fmtU(duty);
  document.getElementById('r-vat').textContent=fmtU(vat);
  document.getElementById('r-wht').textContent=fmtU(wht);
  document.getElementById('r-infra').textContent=fmtU(infra);
  document.getElementById('r-age').textContent=fmtU(envLevy);

  if(age>9){
    document.getElementById('age-levy-row').style.display='flex';
  }else{
    document.getElementById('age-levy-row').style.display='none';
  }
  document.getElementById('r-form').textContent=fmtU(formFees);
  document.getElementById('r-stamp').textContent=fmtU(stampDuty);
  document.getElementById('r-excise').textContent=fmtU(exciseDuty);
  document.getElementById('r-reg').textContent=fmtU(regFees);
  document.getElementById('r-agent').textContent=fmtU(agentFee);
  document.getElementById('t-car').textContent=fmt(carPrice);
  document.getElementById('t-tax').textContent=fmtU(totalTaxes);
  document.getElementById('t-total').textContent=fmtU(totalLanded);
  document.getElementById('uraOverrideNotice').classList.toggle('show',uraCifUsed);
  lastCalcData={carPrice,shipping,insurance,agentFee,cif,duty,vat,wht,infra,envLevy,envLevyRate,age,envLevyApplied:age>9,fixedFees,formFees,stampDuty,exciseDuty,regFees,uraCifUsed,uraCif:currentUraCif||0,totalTaxes,totalLanded};
  const mp=document.getElementById('methodologyPanel');
  if(mp&&mp.classList.contains('open')){buildMethodology(lastCalcData);}
  const make=document.getElementById('make').value;
  const model=document.getElementById('model').value;
  const _chassisVal=document.getElementById('chassis')?.value||'';
  const _ccVal=document.getElementById('cc')?.value||'';
  const vdata=DB.find(x=>x.make===make&&x.model===model&&x.year===year&&
    (!_chassisVal||_chassisVal==='—'||(x.chassis||'—')===_chassisVal)&&
    (!_ccVal||x.cc===_ccVal));
  const chassis=vdata&&vdata.chassis&&vdata.chassis!=='—'?vdata.chassis:'';
  document.getElementById('info-pills').innerHTML=`
    <div class="pill">Age: <span>${age} years</span></div>
    <div class="pill">Tax Rate: <span>~${taxRate}% of price</span></div>
    <div class="pill">Age Levy: <span>${age>9?'Applied':'Not Applied'}</span></div>
    <div class="pill">URA Value: <span>${currentUraCif?fmt(currentUraCif):'Not in DB'}</span></div>
    <div class="pill">Port: <span>Mombasa / Dar es Salaam</span></div>
    ${chassis?`<div class="pill">Chassis: <span>${chassis}</span></div>`:''}
    ${make?`<div class="pill">Vehicle: <span>${make} ${model}</span></div>`:''}${vdata&&vdata.fuel?`<div class="pill">Fuel: <span>${vdata.fuel}</span></div>`:''}${vdata&&vdata.cc?`<div class="pill">Engine: <span>${vdata.cc}cc</span></div>`:''}
  `;
  const r=document.getElementById('results');
  r.classList.add('show');
  r.scrollIntoView({behavior:'smooth',block:'start'});
}

// ── Reliability Section ──────────────────────────────
let lastCalcData = null;
