const ENGINE_COLORS = {"Excellent":"#00d4ff","Good":"#c8ff00","Average":"#ffaa00","Caution":"#ffaa00","Poor":"#ff4444","Avoid":"#ff4444"};
const VERDICT_MAP = {"Average":"Balanced","Caution":"Needs Care","Avoid":"Expert Care","Poor":"High Upkeep"};
const getV = (v) => VERDICT_MAP[v] || v;

// ── Reliability Table ─────────────────────────────────
function renderReliability(data) {
  const tbl = document.getElementById('reliTable');
  const entries = Object.entries(data);
  if(!entries.length) {
    tbl.innerHTML = '<p style="color:var(--muted);font-family:\'DM Mono\',monospace;font-size:13px;padding:12px 0">No brands found</p>';
    return;
  }
  const hdr = ['BRAND','VERDICT','SCORE','COST','PARTS / ENGINES',''].map((h,idx)=>{
    const hideClass = (idx === 2 || idx === 3 || idx === 4) ? ' hide-mobile' : '';
    return `<div class="hdr-cell${hideClass}" style="padding:8px 12px;background:var(--surface2);font-size:10px;font-family:\'DM Mono\',monospace;color:var(--muted);letter-spacing:1.5px;font-weight:600;border-bottom:1px solid var(--border)">${h}</div>`;
  }).join('');
  
  const rows = entries.map(([brand,d],i)=>{
    const dots='●'.repeat(d.score)+'○'.repeat(10-d.score);
    const bg=i%2===0?'transparent':'rgba(255,255,255,0.015)';
    const issues=d.issues.map(x=>`<span style="display:block;padding:1px 0">• ${x}</span>`).join('');
    const hasEng=ENGINES[brand];
    const rowClick=`onclick="toggleRow('r${i}')"`;
    const cell=(content,extra='',click=rowClick, cls='')=>`<div ${click} class="row-cell ${cls}" style="padding:9px 12px;background:${bg};border-top:1px solid var(--border);cursor:pointer;display:flex;align-items:center;${extra}">${content}</div>`;
    
    return `
      <div data-brand="${brand}" style="display:contents">
      ${cell(`<span style="font-size:13px;font-weight:700">${brand}</span>`)}
      ${cell(`<span style="background:${d.color}18;border:1px solid ${d.color}44;border-radius:100px;padding:2px 9px;font-size:10px;color:${d.color};font-family:\'DM Mono\',monospace;font-weight:600;white-space:nowrap">${getV(d.verdict)}</span>`)}
      ${cell(`<span style="font-family:\'DM Mono\',monospace;font-size:11px;color:${d.color};letter-spacing:0.5px" title="${d.score}/10">${dots}</span>`,'','','hide-mobile')}
      ${cell(`<span style="font-family:\'DM Mono\',monospace;font-size:11px;color:var(--muted)">${d.cost}</span>`,'','','hide-mobile')}
      ${cell(
        hasEng
          ? `<button class="eng-btn" onclick="event.stopPropagation();showEngines('${brand}',this)" style="background:rgba(200,255,0,0.08);border:1px solid rgba(200,255,0,0.3);border-radius:6px;color:#c8ff00;font-family:\'DM Mono\',monospace;font-size:10px;padding:4px 9px;cursor:pointer;white-space:nowrap;transition:all 0.15s">🔩 engines</button>`
          : `<span style="font-family:\'DM Mono\',monospace;font-size:11px;color:var(--muted)">${d.parts}</span>`,
        '',rowClick,'hide-mobile'
      )}
      ${cell(`<span style="color:var(--muted);font-size:14px">▾</span>`,'justify-content:center')}
      </div>
      <div id="r${i}" style="display:none;grid-column:1/-1;background:rgba(200,255,0,0.02);border-top:1px solid var(--border);padding:10px 14px;font-family:\'DM Mono\',monospace;font-size:12px;color:var(--muted);line-height:1.9">
        <div class="mobile-extra-info" style="display:none; margin-bottom: 8px; border-bottom: 1px dashed rgba(255,255,255,0.1); padding-bottom: 8px;">
           <span style="color:var(--muted)">Score:</span> <span style="font-family:\'DM Mono\',monospace;color:${d.color};font-weight:600">${d.score}/10</span> &nbsp;&nbsp; 
           <span style="color:var(--muted)">Cost:</span> <span style="color:var(--text)">${d.cost}</span> &nbsp;&nbsp; 
           <span style="color:var(--muted)">Parts:</span> <span style="color:var(--text)">${d.parts}</span>
           ${hasEng ? `<br><button class="eng-btn" onclick="event.stopPropagation();showEngines('${brand}',this)" style="margin-top:8px;background:rgba(200,255,0,0.08);border:1px solid rgba(200,255,0,0.3);border-radius:6px;color:#c8ff00;font-family:\'DM Mono\',monospace;font-size:10px;padding:4px 9px;cursor:pointer;transition:all 0.15s">🔩 engines</button>` : ''}
        </div>
        ${issues}
      </div>`;
  }).join('');
  tbl.innerHTML=`<div style="overflow-x:auto;padding-bottom:8px;margin-bottom:-8px"><div class="reli-grid"><div style="display:contents">${hdr}</div><div style="display:contents">${rows}</div></div></div>`;

  // Apply scroll-trigger observer to rows
  if ('IntersectionObserver' in window) {
    const rowIo = new IntersectionObserver((entries) => {
      let delay = 0;
      entries.forEach(e => {
        if (e.isIntersecting) {
          const cells = e.target.parentElement.querySelectorAll('.row-cell');
          cells.forEach((c) => {
            setTimeout(() => c.classList.add('visible'), delay * 30);
          });
          delay++;
          rowIo.unobserve(e.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -20px 0px' });
    
    tbl.querySelectorAll('[data-brand]').forEach(row => {
      if(row.firstElementChild) rowIo.observe(row.firstElementChild);
    });
  } else {
    tbl.querySelectorAll('.row-cell').forEach(c => c.classList.add('visible'));
  }
}

function toggleRow(id) {
  const el=document.getElementById(id);
  if(el) el.style.display=el.style.display==='none'?'block':'none';
}

function filterReliability() {
  const q=document.getElementById('reliSearch').value.toLowerCase();
  let data=RELI;
  if(activeFilter!=='all') data=Object.fromEntries(Object.entries(data).filter(([,d])=>d.verdict===activeFilter));
  if(q) data=Object.fromEntries(Object.entries(data).filter(([b])=>b.toLowerCase().includes(q)));
  renderReliability(data);
}

function setFilter(verdict) {
  activeFilter = verdict;
  // Update button active states
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-filter') === verdict);
  });
  filterReliability();
}

function setFilterFromSelect() {
  activeFilter=document.getElementById('reliFilter')?.value || 'all';
  document.getElementById('reliSearch').value='';
  filterReliability();
}

filterReliability();

// ── Engine Panel ──────────────────────────────────────
function showEngines(brand, btnEl) {
  if(openEnginePanel===brand){closeEngines();return;}
  closeEngines();
  openEnginePanel=brand;
  const data=ENGINES[brand];
  if(!data) return;
  document.querySelectorAll('.eng-btn').forEach(b=>b.classList.remove('active'));
  btnEl.classList.add('active');
  const sorted=[...data].sort((a,b)=>b.rating-a.rating);
  const panel=document.createElement('div');
  panel.id='enginePanel';
  panel.style.cssText='grid-column:1/-1;background:#0d1117;border-top:1px solid var(--border);padding:16px 14px;animation:fadeUp 0.2s ease';
  panel.innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
      <span style="font-family:\'DM Mono\',monospace;font-size:11px;letter-spacing:2px;color:var(--accent);font-weight:600">🔩 ${brand.toUpperCase()} ENGINE RELIABILITY</span>
      <button onclick="closeEngines()" style="background:none;border:1px solid var(--border);border-radius:6px;color:var(--muted);font-size:11px;padding:3px 10px;cursor:pointer;font-family:\'DM Mono\',monospace">✕ close</button>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">
      ${sorted.map(e=>{
        const col=ENGINE_COLORS[e.verdict]||'#6b7280';
        const dots='●'.repeat(e.rating)+'○'.repeat(10-e.rating);
        return `<div style="background:${col}0d;border:1px solid ${col}33;border-radius:10px;padding:12px 14px">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px">
            <span style="font-size:13px;font-weight:700;line-height:1.3;flex:1;padding-right:8px">${e.engine}</span>
            <span style="background:${col}22;border:1px solid ${col}44;border-radius:100px;padding:2px 8px;font-size:10px;color:${col};font-family:\'DM Mono\',monospace;font-weight:600;white-space:nowrap">${getV(e.verdict)}</span>
          </div>
          <div style="font-family:\'DM Mono\',monospace;font-size:11px;color:${col};margin-bottom:8px" title="${e.rating}/10">${dots}</div>
          <p style="font-family:\'DM Mono\',monospace;font-size:11px;color:var(--muted);line-height:1.7;margin:0">${e.notes}</p>
        </div>`;
      }).join('')}
    </div>`;
  const row=document.querySelector(`[data-brand="${brand}"]`);
  if(row && row.nextElementSibling) {
    row.parentElement.insertBefore(panel, row.nextElementSibling.nextSibling);
  }
}

function closeEngines() {
  const p=document.getElementById('enginePanel');
  if(p) p.remove();
  document.querySelectorAll('.eng-btn').forEach(b=>b.classList.remove('active'));
  openEnginePanel=null;
}

// ── Methodology Panel ─────────────────────────────────
function toggleMethodology() {
  const panel=document.getElementById('methodologyPanel');
  const arrow=document.getElementById('methArrow');
  const btn=document.getElementById('methBtn');
  const isOpen=panel.classList.contains('open');
  if(isOpen){
    panel.style.display='none';
    panel.classList.remove('open');
    arrow.style.transform='rotate(0deg)';
    btn.style.borderColor='var(--border)';btn.style.color='var(--muted)';
  } else {
    if(!lastCalcData){alert('Please calculate taxes first, then view the methodology.');return;}
    buildMethodology(lastCalcData);
    panel.style.display='block';
    panel.classList.add('open');
    arrow.style.transform='rotate(180deg)';
    btn.style.borderColor='var(--accent)';btn.style.color='var(--accent)';
    panel.scrollIntoView({behavior:'smooth',block:'nearest'});
  }
}

function buildMethodology(d) {
  // fmt, fmtU, UGX are defined globally above
  const c=d.cif,duty=d.duty,vat=d.vat,wht=d.wht,infra=d.infra,env=d.envLevy,agent=d.agentFee;
  const price=d.carPrice,ship=d.shipping,ins=d.insurance;
  const hasEnv=d.envLevyApplied;
  const uraUsed=d.uraCifUsed;
  const taxBase=uraUsed?d.uraCif:price;
  const steps=[
    {num:'01',color:'#00d4ff',title:'Establish Taxable CIF Value',formula:uraUsed?'CIF = URA official CIF valuation':'CIF = Purchase Price + Shipping + Insurance',calc:uraUsed?`CIF = ${fmt(c)}`:`CIF = ${fmt(price)} + ${fmt(ship)} + ${fmt(ins)} = ${fmt(c)}`,note:uraUsed?`URA's official Motor Vehicle Value Guide CIF (${fmt(c)}) is used for all tax calculations as per your request.`:`Your purchase price plus shipping and insurance forms the CIF cost base. URA will override if their Motor Vehicle Value Guide is found.`},
    {num:'02',color:'#ffaa00',title:'Import Duty — 25%',formula:'Import Duty = CIF × 25%',calc:`Import Duty = ${fmt(c)} × 0.25 = ${fmt(duty)}`,note:'Levied under the EAC Common External Tariff (CET). Passenger vehicles (HS Code 8703.xx) attract 25% import duty. Paid at customs clearance.'},
    {num:'03',color:'#ffaa00',title:'Value Added Tax (VAT) — 18%',formula:'VAT = (CIF + Duty) × 18%',calc:`VAT = (${fmt(c)} + ${fmt(duty)}) × 0.18 = ${fmt(vat)}`,note:'VAT is charged at 18% of the CIF value plus Import Duty. This reflects the standard landed value calculation for motor vehicles.'},
    {num:'04',color:'#ffaa00',title:'Withholding Tax — 6%',formula:'WHT = CIF × 6%',calc:`WHT = ${fmt(c)} × 0.06 = ${fmt(wht)}`,note:'Prepayment of income tax collected at customs. Applied on CIF value only. Private importers may offset this against their annual income tax return with URA.'},
    {num:'05',color:'#ffaa00',title:'Infrastructure Levy — 1.5%',formula:'Infrastructure Levy = CIF × 1.5%',calc:`Infrastructure Levy = ${fmt(c)} × 0.015 = ${fmt(infra)}`,note:'Road infrastructure development fund. Applied on CIF value only. Paid at customs alongside import duty.'},
    ...(hasEnv?[{num:'06',color:'#ff4444',title:`Environmental Levy — 50% (Vehicle is ${d.age} years old)`,formula:'Environmental Levy = CIF × 50%  [vehicles aged 10–14 years]',calc:`Environmental Levy = ${fmt(c)} × 0.50 = ${fmt(env)}`,note:`⚠️ Your vehicle is ${d.age} years old. The environmental levy applies to all vehicles aged 10–14 years at 50% of CIF. Vehicles under 10 years pay 0%. Vehicles over 15 years cannot be imported. Collected at vehicle registration, not at customs.`}]:[{num:'06',color:'#00d4ff',title:`Environmental Levy — 0% (Vehicle is ${d.age} years old)`,formula:'Environmental Levy = 0%  [vehicles under 10 years]',calc:`No environmental levy — vehicle is only ${d.age} years old ✅`,note:`The environmental levy only applies to vehicles aged 10 years and older. Your vehicle is in the zero-levy band.`}]),
    {num:'07',color:'#6b7280',title:'Fixed Government Fees (UGX)',formula:'Form Fees + Stamp Duty + Excise Duty + Registration Fees',calc:`UGX 18,000 + UGX 200,000 + UGX 200,000 + UGX 1,500,000 = UGX 1,918,000 ≈ ${fmt(d.fixedFees)}`,note:'Fixed UGX fees regardless of vehicle value. Form Fees and Stamp Duty are documentation charges paid at customs. Excise Duty and Registration Fees are paid at DVLA when registering in Uganda.'},
    {num:'08',color:'#6b7280',title:'Clearing Agent Fee',formula:'Agent Fee = your negotiated amount (not a URA tax)',calc:`Agent Fee = ${fmt(agent)}`,note:'Paid to your licensed clearing agent for customs documentation, URA liaison, port handling and inland transport. Not a government charge — varies by agent and port.'},
  ];
  document.getElementById('methSteps').innerHTML=steps.map(s=>`
    <div style="border:1px solid ${s.color}33;border-radius:10px;overflow:hidden">
      <div style="background:${s.color}10;padding:12px 16px;display:flex;align-items:center;gap:12px;border-bottom:1px solid ${s.color}22">
        <span style="background:${s.color}22;border:1px solid ${s.color}44;border-radius:6px;padding:3px 9px;font-family:\'DM Mono\',monospace;font-size:11px;font-weight:700;color:${s.color}">STEP ${s.num}</span>
        <span style="font-weight:700;font-size:14px">${s.title}</span>
      </div>
      <div style="padding:14px 16px;display:flex;flex-direction:column;gap:8px">
        <div style="background:var(--surface2);border-radius:8px;padding:10px 14px;font-family:\'DM Mono\',monospace;font-size:12px;color:${s.color}">${s.formula}</div>
        <div style="background:rgba(0,0,0,0.3);border-radius:8px;padding:10px 14px;font-family:\'DM Mono\',monospace;font-size:13px;color:var(--text);font-weight:600">${s.calc}</div>
        <p style="font-family:\'DM Mono\',monospace;font-size:11px;color:var(--muted);line-height:1.7;margin:0">${s.note}</p>
      </div>
    </div>`).join('');
  const customsTotal=duty+vat+wht+infra+d.fixedFees+agent;
  const totalAll=customsTotal+env;
  const landed=price+ship+ins+totalAll;
  document.getElementById('methChain').innerHTML=`
    <div style="display:flex;flex-direction:column;gap:4px">
      <div style="display:flex;justify-content:space-between"><span style="color:var(--accent2)">Purchase Price</span><span>${fmt(price)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ Shipping</span><span>${fmt(ship)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ Insurance</span><span>${fmt(ins)}</span></div>
      <div style="border-top:1px solid var(--border);margin:4px 0;padding-top:4px;display:flex;justify-content:space-between;font-weight:700"><span style="color:var(--accent2)">= CIF (taxable base)</span><span style="color:var(--accent2)">${fmt(c)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ Import Duty (25% of CIF)</span><span style="color:var(--warning)">${fmtU(duty)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ VAT (18% of CIF + Duty)</span><span style="color:var(--warning)">${fmtU(vat)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ Withholding Tax (6% of CIF)</span><span style="color:var(--warning)">${fmtU(wht)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ Infrastructure Levy (1.5% of CIF)</span><span style="color:var(--warning)">${fmtU(infra)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ Fixed Gov't Fees</span><span style="color:var(--warning)">${fmtU(d.fixedFees)}</span></div>
      <div style="display:flex;justify-content:space-between"><span>+ Clearing Agent Fee</span><span style="color:var(--muted)">${fmtU(agent)}</span></div>
      <div style="border-top:1px solid var(--border);margin:4px 0;padding-top:4px;display:flex;justify-content:space-between;font-weight:600"><span style="color:var(--warning)">= Customs Total </span><span style="color:var(--warning)">${fmtU(customsTotal)}</span></div>
      ${hasEnv?`<div style="display:flex;justify-content:space-between"><span>+ Environmental Levy (50%) <span style="font-size:10px;color:var(--muted)">at registration</span></span><span style="color:var(--danger)">${fmtU(env)}</span></div>`:`<div style="display:flex;justify-content:space-between"><span>+ Environmental Levy</span><span style="color:var(--accent2)">UGX 0 (under 10 years)</span></div>`}
      <div style="border-top:2px solid var(--accent);margin:6px 0;padding-top:6px;display:flex;justify-content:space-between;font-size:15px;font-weight:800"><span style="color:var(--accent)">= TOTAL LANDED COST</span><span style="color:var(--accent)">${fmtU(landed)}</span></div>
      <div style="display:flex;justify-content:space-between;margin-top:2px;font-size:11px"><span style="color:var(--muted)">Total taxes as % of car price</span><span style="color:var(--muted)">${Math.round((totalAll/price)*100)}%</span></div>
    </div>`;
}

// ==========================================
// SCROLL REVEAL ANIMATIONS
// ==========================================
document.addEventListener('DOMContentLoaded', () => {
  const animElements = document.querySelectorAll('.reveal, .reveal-left, .reveal-right, .reveal-scale');
  
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver((entries) => {
      let delayCount = 0;
      entries.forEach(e => {
        if (e.isIntersecting) {
          // Stagger the animation when items scroll into view
          setTimeout(() => e.target.classList.add('visible'), delayCount * 100);
          delayCount++;
          // Unobserve if we only want it to animate once (we'll let it play bidirectionally for now)
        } else {
          // Remove visible class when out of view so it animates again when scrolling back
          e.target.classList.remove('visible');
        }
      });
    }, { threshold: 0.1 });

    animElements.forEach(el => io.observe(el));
  } else {
    // Fallback for very old browsers: just make everything visible immediately
    animElements.forEach(el => el.classList.add('visible'));
  }
});